// Coin chime + tavern ambience. Uses /sfx/*.mp3 when present (generated by scripts/gen-sfx.ts), else a WebAudio beep.
let ctx: AudioContext | null = null;
let coinAvailable: boolean | null = null;
let ambienceStarted = false;

function audioCtx(): AudioContext | null {
  try {
    if (!ctx) ctx = new AudioContext();
    if (ctx.state === 'suspended') void ctx.resume();
    return ctx;
  } catch {
    return null;
  }
}

async function exists(url: string): Promise<boolean> {
  try {
    const r = await fetch(url, { method: 'HEAD' });
    const type = r.headers.get('content-type') || '';
    return r.ok && !type.includes('text/html'); // SPA fallback returns HTML for missing files
  } catch {
    return false;
  }
}

function beep() {
  const c = audioCtx();
  if (!c) return;
  const t = c.currentTime;
  for (const [i, f] of [1318.5, 1760].entries()) {
    const o = c.createOscillator();
    const g = c.createGain();
    o.type = 'triangle';
    o.frequency.value = f;
    g.gain.setValueAtTime(0.0001, t + i * 0.08);
    g.gain.exponentialRampToValueAtTime(0.25, t + i * 0.08 + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + i * 0.08 + 0.25);
    o.connect(g).connect(c.destination);
    o.start(t + i * 0.08);
    o.stop(t + i * 0.08 + 0.3);
  }
}

export async function playCoin() {
  if (coinAvailable === null) coinAvailable = await exists('/sfx/coin.mp3');
  if (coinAvailable) {
    const a = new Audio('/sfx/coin.mp3');
    a.volume = 0.7;
    a.play().catch(() => beep());
  } else beep();
}

/** Call from a user gesture (autoplay policy). Silently skipped if the file is missing. */
export async function startAmbience() {
  if (ambienceStarted) return;
  ambienceStarted = true;
  audioCtx();
  if (!(await exists('/sfx/tavern-ambience.mp3'))) return;
  const a = new Audio('/sfx/tavern-ambience.mp3');
  a.loop = true;
  a.volume = 0.12;
  a.play().catch(() => {
    ambienceStarted = false;
  });
}
